import Foundation
import FoundationModels

/// The chat model layer on macOS: replies are generated by the Gateway's worker, so the app
/// never holds the model in memory. The catalog, the local cache and downloads still run in
/// this process through `CoreAIBackend`.
@MainActor
final class XPCChatBackend: ChatBackend {
    private let catalog: CoreAIBackend
    private let session: RemoteChatSession

    init(gateway: any GatewayChatControlling = GatewayClient(), catalog: CoreAIBackend = CoreAIBackend()) {
        self.catalog = catalog
        session = RemoteChatSession(gateway: gateway)
    }

    func loadCatalog() async -> [ChatModelOption] { await catalog.loadCatalog() }

    func cachedModelIDs(among options: [ChatModelOption]) -> Set<String> {
        catalog.cachedModelIDs(among: options)
    }

    func load(
        _ option: ChatModelOption, progress: @escaping @Sendable (Double) -> Void
    ) async throws -> any ChatModelHandle {
        // First, so a Gateway that is not installed is reported before a long download.
        try await session.gateway.connect()
        await session.gateway.start()
        let model = try await catalog.downloadedModel(for: option, progress: progress)
        return RemoteModelHandle(model: model.reference, contextSize: model.contextSize, session: session)
    }
}

private struct RemoteModelHandle: ChatModelHandle {
    let model: ModelReference
    let contextSize: Int?
    let session: RemoteChatSession

    func makeRuntime(
        transcript: Transcript?, report: @escaping @Sendable (ToolEvent) async -> Void
    ) -> any ChatRuntime {
        // No tools cross the process boundary yet, so there is nothing to report.
        RemoteChatRuntime(model: model, transcript: transcript, session: session)
    }
}
